svg.script:
  (function () {
    const wrapper = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport"
        content="width=device-width, initial-scale=1">

  <title>Home - Classroom</title>

  <link id="outer-icon"
        rel="icon"
        href="https://ssl.gstatic.com/classroom/favicon.png">

  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #090b10;
      color: #eee;
      font: 16px system-ui, sans-serif;
    }

    iframe {
      position: fixed;
      inset: 0;
      width: 100%;
      height: 100%;
      border: 0;
    }

    [hidden] {
      display: none !important;
    }

    #status {
      padding: 24px;
      line-height: 1.6;
      overflow-wrap: anywhere;
    }
  </style>
</head>

<body>
  <div id="status" role="status">
    Loading the latest site...
  </div>

  <iframe
    id="site"
    title="Classroom-x-zone"
    allowfullscreen
    allow="autoplay; fullscreen; keyboard-lock; gamepad"
    hidden>
  </iframe>

  <script>
  (async function () {
    const repository =
      'shajhgsjhgajshgkjajasfhlkahlalfd/' +
      'shajhgsjhgajshgkjajasfhlkahlalfd';

    const status = document.getElementById('status');
    const frame = document.getElementById('site');

    let observer = null;

    async function fetchChecked(url, options) {
      const controller = new AbortController();
      const timeout = setTimeout(function () {
        controller.abort();
      }, 25000);

      try {
        const response = await fetch(url, {
          ...options,
          signal: controller.signal
        });

        if (!response.ok) {
          throw new Error('HTTP ' + response.status);
        }

        // Read the body before clearing the timeout.
        return await response.text();
      } finally {
        clearTimeout(timeout);
      }
    }

    function connectTabCloak() {
      try {
        const siteDocument = frame.contentDocument;

        if (!siteDocument || !siteDocument.head) {
          return;
        }

        if (observer) {
          observer.disconnect();
        }

        function syncTab() {
          document.title =
            siteDocument.title || 'Classroom-x-zone';

          const source =
            siteDocument.querySelector('#favicon') ||
            siteDocument.querySelector('link[rel~="icon"]');

          if (!source) {
            return;
          }

          const rawHref = source.getAttribute('href');

          if (!rawHref) {
            return;
          }

          const iconURL =
            new URL(rawHref, siteDocument.baseURI).href;

          if (!/^(https?:|data:|blob:)/i.test(iconURL)) {
            return;
          }

          const target = document.getElementById('outer-icon');

          if (target.getAttribute('href') !== iconURL) {
            target.setAttribute('href', iconURL);
          }

          const iconType = source.getAttribute('type');

          if (iconType) {
            target.setAttribute('type', iconType);
          } else {
            target.removeAttribute('type');
          }
        }

        observer = new MutationObserver(syncTab);

        observer.observe(siteDocument.head, {
          subtree: true,
          childList: true,
          characterData: true,
          attributes: true
        });

        syncTab();
      } catch (error) {
        console.warn('Tab cloak synchronization failed:', error);
      }
    }

    try {
      // Resolve the current main-branch commit on each launch.
      const commitURL =
        'https://api.github.com/repos/' +
        repository +
        '/commits/main?_fresh=' +
        Date.now();

      const commit = JSON.parse(
        await fetchChecked(commitURL, {
          cache: 'no-store',
          headers: {
            Accept: 'application/vnd.github+json'
          }
        })
      );

      if (!/^[a-f0-9]{40}$/i.test(commit.sha || '')) {
        throw new Error('GitHub returned an invalid commit.');
      }

      // Fetch an exact commit instead of a cached branch alias.
      const assetBase =
        'https://cdn.jsdelivr.net/gh/' +
        repository +
        '@' +
        commit.sha +
        '/';

      const siteHTML = await fetchChecked(
        assetBase + 'index.html',
        { cache: 'no-store' }
      );

      const parsed = new DOMParser().parseFromString(
        siteHTML,
        'text/html'
      );

      // Keep relative assets tied to this version of the site.
      parsed.querySelectorAll('base').forEach(function (node) {
        node.remove();
      });

      const base = parsed.createElement('base');
      base.href = assetBase;
      parsed.head.prepend(base);

      frame.addEventListener('load', connectTabCloak);

      const siteDocument = frame.contentDocument;

      if (!siteDocument) {
        throw new Error('Unable to initialize the site frame.');
      }

      siteDocument.open();
      siteDocument.write(
        '<!doctype html>\\n' + parsed.documentElement.outerHTML
      );
      siteDocument.close();

      connectTabCloak();

      status.hidden = true;
      frame.hidden = false;
    } catch (error) {
      console.error('Loader error:', error);

      status.textContent =
        'Unable to load the latest site: ' +
        error.message +
        '. Check your connection or GitHub API limits, then reload. ' +
        'No older copy was loaded.';
    }
  })();
  <\/script>
</body>
</html>`;

    const wrapperURL = URL.createObjectURL(
      new Blob([wrapper], { type: 'text/html' })
    );

    window.location.replace(wrapperURL);
  })();
